package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The people kept on a sheet. */
@Service
public class PersonService {

    private final PersonRepository people;
    private final PatronRepository patrons;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public PersonService(PersonRepository people, PatronRepository patrons, SheetService sheets, RollupService rollup, Audit audit) {
        this.people = people;
        this.patrons = patrons;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** The sheet's today, which the grade a person is listed with is in force on. */
    @Transactional
    public LocalDate today(String sheetId) {
        return sheets.load(sheetId).getToday();
    }

    /** Adds the person with no terms of their own. */
    @Transactional
    public Person add(String by, String sheetId, String name, String grade) {
        return add(by, sheetId, name, grade, null);
    }

    /**
     * Adds the person with their own terms (null: none); the grade they are given first applies from the beginning
     * of time.
     */
    @Transactional
    public Person add(String by, String sheetId, String name, String grade, Integer terms) {
        LocalDate today = sheets.load(sheetId).getToday();
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        String trimmed = name.strip();
        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, trimmed)) {
            throw nameInUse();
        }
        Person person = new Person(sheetId, trimmed, grade, today);
        person.setTerms(terms);
        Person added = save(person);
        audit.recordOnCommit(record("PERSON_ADDED", by, added, today(sheetId))
                + (terms != null ? " terms=" + terms : ""));
        rollup.recordChanges(by, sheetId, before);
        return added;
    }

    /**
     * Saves an edit made from the given version of the person; refused when it has been saved since. The grade is
     * recorded from the from-date (missing: the sheet's today), keeping the ones already recorded, except that an
     * edit leaving the grade in force today as it is, with no from-date, records nothing. The person's own terms are
     * set to the given ones (null: none).
     */
    @Transactional
    public Person update(String by, String sheetId, Long id, long version, String name, String grade,
            LocalDate gradeFrom, Integer terms) {
        LocalDate today = today(sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        if (person.getVersion() != version) {
            throw stale();
        }
        String trimmed = name.strip();
        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, id)) {
            throw nameInUse();
        }
        person.setName(trimmed);
        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
            person.recordGrade(grade, gradeFrom != null ? gradeFrom : today, today);
        }
        boolean termsChanged = !Objects.equals(terms, person.getTerms());
        person.setTerms(terms);
        Person saved = save(person);
        audit.recordOnCommit(record("PERSON_EDITED", by, saved, today)
                + (termsChanged ? " terms=" + (terms != null ? terms : "") : ""));
        rollup.recordChanges(by, sheetId, before);
        return saved;
    }

    /** Retires the person from the date; a missing date takes the sheet's today. Their claims keep counting. */
    @Transactional
    public Person retire(String by, String sheetId, Long id, LocalDate from) {
        LocalDate today = sheets.load(sheetId).getToday();
        LocalDate on = from != null ? from : today;
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person person = people.findWithLockByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        person.setRetiredFrom(on, today);
        Person saved = save(person);
        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + by + " name=" + saved.getName()
                + " from=" + on);
        rollup.recordChanges(by, sheetId, before);
        return saved;
    }

    /**
     * Puts a hold on the person from the date (missing: the sheet's today) to the to-date (missing: with no end); the
     * holds already put are kept, each ending on its to-date. Their open claims dated within a hold, not bound by a
     * statement, count in no live total. Refused when the to-date is before the from-date.
     */
    @Transactional
    public Person hold(String by, String sheetId, Long id, LocalDate from, LocalDate to) {
        LocalDate today = sheets.load(sheetId).getToday();
        LocalDate on = from != null ? from : today;
        if (to != null && to.isBefore(on)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person person = people.findWithLockByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        person.addHold(on, to, today);
        Person saved = save(person);
        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + by + " name=" + saved.getName()
                + " from=" + on);
        rollup.recordChanges(by, sheetId, before);
        return saved;
    }

    @Transactional(readOnly = true)
    public List<Patron> patrons(String sheetId) {
        return patrons.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Names another person on the sheet as the person's patron; never themselves, nor anyone twice. */
    @Transactional
    public Patron addPatron(String by, String sheetId, Long id, Long patronId) {
        Person person = people.findWithLockByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron."));
        if (person.getId().equals(patron.getId())) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A person cannot be their own patron.");
        }
        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
            throw patronNamed();
        }
        Patron added;
        try {
            added = patrons.saveAndFlush(new Patron(sheetId, person.getId(), patron.getId()));
        } catch (DataIntegrityViolationException e) {
            throw patronNamed();
        }
        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + by + " name=" + person.getName()
                + " patron=" + patron.getName());
        return added;
    }

    /** Saves the person; the store's unique index refuses a name another request took meanwhile. */
    private Person save(Person person) {
        try {
            return people.saveAndFlush(person);
        } catch (DataIntegrityViolationException e) {
            throw nameInUse();
        } catch (ObjectOptimisticLockingFailureException e) {
            // another request saved the person between this one reading and writing it
            throw stale();
        }
    }

    /** The audit line about a person, with the grade in force on the sheet's today. */
    private static String record(String event, String by, Person p, LocalDate today) {
        return event + " sheet=" + p.getSheetId() + " by=" + by + " name=" + p.getName() + " grade="
                + p.gradeOn(today);
    }

    private static ResponseStatusException stale() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
                "Someone else has saved this person since it was opened.");
    }

    private static ResponseStatusException patronNamed() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That person is already one of their patrons.");
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.session.SessionController;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.SessionAttribute;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/people")
public class PersonController {

    /**
     * A person as listed: the grade is the one in force on the sheet's today, the grades every one recorded, the
     * terms their own (null: none).
     */
    public record PersonView(Long id, String name, String grade, List<GradeView> grades, long version,
            LocalDate retiredFrom, boolean held, List<HoldView> holds, Integer terms) {
        public static PersonView of(Person p, LocalDate today) {
            return new PersonView(p.getId(), p.getName(), p.gradeOn(today),
                    p.getGrades().stream().map(GradeView::of).toList(), p.getVersion(), p.getRetiredFrom(),
                    p.isHeld(), p.getHolds().stream().map(HoldView::of).toList(), p.getTerms());
        }
    }

    /** A hold on a person from its from-date to its to-date (null: with no end). */
    public record HoldView(LocalDate from, LocalDate to) {
        public static HoldView of(DatedHold h) {
            return new HoldView(h.getFrom(), h.getTo());
        }
    }

    /** A grade a person has from its from-date (null: from the beginning of time). */
    public record GradeView(String grade, LocalDate from) {
        public static GradeView of(DatedGrade g) {
            return new GradeView(g.getGrade(), g.getFrom());
        }
    }

    /**
     * A person's fields as the form submits them; the name is stored without surrounding spaces, the terms are whole
     * days, 0 or more, or null for none.
     */
    public record PersonForm(@NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade, @Min(0) @Max(99999) Integer terms) {
    }

    /**
     * An edit of a person: its fields, the date its grade applies from (missing: the sheet's today) and the version
     * of the person the editor loaded, and their own terms (null: none).
     */
    public record PersonEdit(@NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade, LocalDate gradeFrom, @NotNull Long version,
            @Min(0) @Max(99999) Integer terms) {
    }

    /** One person named as another's patron. */
    public record PatronView(Long id, Long personId, Long patronId) {
        public static PatronView of(Patron p) {
            return new PatronView(p.getId(), p.getPersonId(), p.getPatronId());
        }
    }

    /** A patron to add: the id of another person on the sheet. */
    public record PatronForm(@NotNull Long patronId) {
    }

    /** A retirement: the date it takes effect; a missing date takes the sheet's today. */
    public record RetireForm(LocalDate from) {
    }

    /** A hold: the date it starts (missing: the sheet's today) and the date it ends (missing: with no end). */
    public record HoldForm(LocalDate from, LocalDate to) {
    }

    /** Whether the signed-in user is to watch the person. */
    public record WatchForm(@NotNull Boolean on) {
    }

    /** Whether the signed-in user watches the person now. */
    public record WatchView(Long personId, boolean watched) {
    }

    private final PersonService service;
    private final WatchService watches;

    public PersonController(PersonService service, WatchService watches) {
        this.service = service;
        this.watches = watches;
    }

    /** All the people on the sheet, in the order they were added. */
    @GetMapping
    public List<PersonView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        LocalDate today = service.today(sheetId);
        return service.list(sheetId).stream().map(p -> PersonView.of(p, today)).toList();
    }

    @PostMapping
    public PersonView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody PersonForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return view(sheetId, service.add(user, sheetId, form.name(), form.grade(), form.terms()));
    }

    @PutMapping("/{id}")
    public PersonView update(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @Valid @RequestBody PersonEdit form,
            @SessionAttribute(SessionController.USER) String user) {
        return view(sheetId,
                service.update(user, sheetId, id, form.version(), form.name(), form.grade(), form.gradeFrom(),
                        form.terms()));
    }

    @PostMapping("/{id}/retire")
    public PersonView retire(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @RequestBody RetireForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return view(sheetId, service.retire(user, sheetId, id, form.from()));
    }

    /** Puts a hold on the person, from its from-date to its to-date; the holds already put are kept. */
    @PostMapping("/{id}/hold")
    public PersonView hold(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @RequestBody HoldForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return view(sheetId, service.hold(user, sheetId, id, form.from(), form.to()));
    }

    /** The person as listed on the sheet's today. */
    private PersonView view(String sheetId, Person person) {
        return PersonView.of(person, service.today(sheetId));
    }

    /** The ids of the people on the sheet the signed-in user watches, in the order they started watching. */
    @GetMapping("/watched")
    public List<Long> watched(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @SessionAttribute(SessionController.USER) String user) {
        return watches.watched(sheetId, user);
    }

    /** Starts or stops the signed-in user watching the person. */
    @PostMapping("/{id}/watch")
    public WatchView watch(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @Valid @RequestBody WatchForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return new WatchView(id, watches.watch(user, sheetId, id, form.on()));
    }

    /** Every patron named on the sheet, in the order they were named. */
    @GetMapping("/patrons")
    public List<PatronView> patrons(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        return service.patrons(sheetId).stream().map(PatronView::of).toList();
    }

    /** Names another person on the sheet as the person's patron; refused for themselves or one already named. */
    @PostMapping("/{id}/patrons")
    public PatronView addPatron(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable Long id, @Valid @RequestBody PatronForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return PatronView.of(service.addPatron(user, sheetId, id, form.patronId()));
    }
}
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.settings.SettingsService;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

/** Status changes made to several claims together, each one on its own. */
@Service
public class ClaimBulkService {

    /** The claims a bulk action changed, in the order it took them, and how many it refused. */
    public record Result(List<Claim> changed, int refused) {
    }

    private final ClaimService claims;
    private final ClaimRepository repository;
    private final PersonRepository people;
    private final SettingsService settings;

    public ClaimBulkService(ClaimService claims, ClaimRepository repository, PersonRepository people,
            SettingsService settings) {
        this.claims = claims;
        this.repository = repository;
        this.people = people;
        this.settings = settings;
    }

    /**
     * Opens each of the claims that can be opened, in list order (the order of people, newest claim first within a
     * person), so they are numbered in that order. Each is opened in its own transaction: one that is refused, or is
     * not a claim of the sheet, is left as it is and counted as refused.
     */
    public Result open(String by, String sheetId, Set<Long> ids) {
        return each(by, sheetId, ids, id -> claims.changeStatus(by, sheetId, id, ClaimStatus.OPEN));
    }

    /**
     * Settles each of the claims that can be settled, in list order, by the rules of settling one claim: one the
     * clerk limit makes PENDING counts as settled. Each is settled in its own transaction: one that is refused, or is
     * not a claim of the sheet, is left as it is and counted as refused.
     */
    public Result settle(String by, String sheetId, Set<Long> ids) {
        return each(by, sheetId, ids, id -> claims.changeStatus(by, sheetId, id, ClaimStatus.SETTLED));
    }

    /**
     * Applies the change to each of the sheet's claims among the ids in list order, counting the refused ones. A
     * viewer, or anyone on an archived sheet, changes none: every one is refused.
     */
    private Result each(String by, String sheetId, Set<Long> ids, Function<Long, Claim> change) {
        if (settings.isReadOnly(sheetId, by)) {
            return new Result(List.of(), ids.size());
        }
        Map<Long, Integer> personOrder = new HashMap<>();
        for (Person p : people.findBySheetIdOrderByIdAsc(sheetId)) {
            personOrder.put(p.getId(), personOrder.size());
        }
        List<Long> ordered = repository.findBySheetIdOrderByListedDescIdDesc(sheetId).stream()
                .filter(c -> ids.contains(c.getId()))
                .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                        .thenComparing(Claim::getListed, Comparator.reverseOrder())
                        .thenComparing(Claim::getId, Comparator.reverseOrder()))
                .map(Claim::getId).toList();
        List<Claim> changed = new ArrayList<>();
        int refused = ids.size() - ordered.size();
        for (Long id : ordered) {
            try {
                changed.add(change.apply(id));
            } catch (ResponseStatusException e) {
                refused++;
            }
        }
        return new Result(changed, refused);
    }
}
