package net.officefloor.hq.app.settings;


/**
 * Refuses a viewer, and anyone on an archived sheet, every request that changes a sheet, before it reaches its
 * handler, so it writes nothing. A handler marked {@link ViewerPasses} is let through.
 */
@Component
public class ViewerGuard implements HandlerInterceptor {

    private final SettingsService settings;

    public ViewerGuard(SettingsService settings) {
        this.settings = settings;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (!(handler instanceof HandlerMethod method) || HttpMethod.GET.matches(request.getMethod())
                || method.hasMethodAnnotation(ViewerPasses.class)) {
            return true;
        }
        HttpSession session = request.getSession(false);
        Object user = session == null ? null : session.getAttribute(SessionController.USER);
        String sheetId = sheetId(request);
        if (sheetId != null && settings.isArchived(sheetId)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The sheet is archived; nothing on it can change.");
        }
        if (user instanceof String name && sheetId != null && settings.isViewer(sheetId, name)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "A viewer may not change anything.");
        }
        return true;
    }

    /** The sheet the request is on: its sheetId path variable, or the id of a /api/sheets/{id} path. */
    public static String sheetId(HttpServletRequest request) {
        @SuppressWarnings("unchecked")
        Map<String, String> vars = (Map<String, String>) request
                .getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        if (vars == null) {
            return null;
        }
        String sheetId = vars.get("sheetId");
        if (sheetId == null && request.getRequestURI().startsWith(request.getContextPath() + "/api/sheets/")) {
            sheetId = vars.get("id");
        }
        return sheetId;
    }
}
package net.officefloor.hq.app.asof;


/**
 * A screen showing a sheet as of a date sends that date with each request ({@link #HEADER}). Such a request is
 * answered from the sheet as it stood at the end of the date (see {@link AsOfService#storeAsOf}), and every request
 * that changes the sheet is refused before it reaches its handler, so it writes nothing. A handler marked
 * {@link AsOfReads} changes nothing and is answered as of the date.
 */
@Component
public class AsOfGuard implements HandlerInterceptor {

    /** The request header carrying the date the screen shows the sheet as of (yyyy-mm-dd). */
    public static final String HEADER = "X-As-Of";

    private final AsOfService asOf;

    public AsOfGuard(AsOfService asOf) {
        this.asOf = asOf;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        String header = request.getHeader(HEADER);
        String sheetId = ViewerGuard.sheetId(request);
        if (header == null || header.isBlank() || !(handler instanceof HandlerMethod method) || sheetId == null) {
            return true;
        }
        LocalDate day;
        try {
            day = LocalDate.parse(header.trim());
        } catch (DateTimeParseException e) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The as-of date is not a date.");
        }
        if (!HttpMethod.GET.matches(request.getMethod()) && !method.hasMethodAnnotation(AsOfReads.class)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "The sheet is shown as of a date; nothing on it can change.");
        }
        AsOfContext.enter(asOf.storeAsOf(sheetId, day));
        return true;
    }

    @Override
    public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler,
            Exception ex) {
        AsOfContext.leave();
    }
}
package net.officefloor.hq.app;


/**
 * Guards the API: a screen showing a sheet as of a date is answered as of it and refused every change; a viewer, or
 * anyone on an archived sheet, is refused every change.
 */
@Configuration
public class WebConfig implements WebMvcConfigurer {

    private final AsOfGuard asOfGuard;
    private final ViewerGuard viewerGuard;

    public WebConfig(AsOfGuard asOfGuard, ViewerGuard viewerGuard) {
        this.asOfGuard = asOfGuard;
        this.viewerGuard = viewerGuard;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(asOfGuard).addPathPatterns("/api/**");
        registry.addInterceptor(viewerGuard).addPathPatterns("/api/**");
    }
}

